ALTER TABLE "attempts" DROP CONSTRAINT "attempts_outcome_matches_rule";--> statement-breakpoint
ALTER TABLE "attempts" ADD CONSTRAINT "attempts_outcome_matches_rule" CHECK ("attempts"."outcome" = case when rule_code in ('R7_WITHIN_LIMITS', 'OWNER_APPROVED') then 'PAID' when rule_code in ('VARIANT_MISMATCH', 'OFFER_NOT_FOUND', 'CHOSEN_UNAVAILABLE', 'R3_STEERED', 'R4_OVERPAID') then 'REJECTED' when rule_code in ('R1_STALE_SNAPSHOT', 'CHOSEN_UNVERIFIED', 'R2_TOO_FEW_OFFERS', 'R2A_GAP_IMPLAUSIBLE', 'R4A_NO_CLASSIFIER_ANSWER', 'R5_COMMISSION_CONFLICT', 'R6_ABOVE_ORDER_CAP') then 'HELD' end);